function remap(r,map,keepReview){const out={done:[],notes:{}};for(const i of Array.isArray(r?.done)?r.done:[]){const j=map[i];if(Number.isInteger(j)&&j>=0)out.done.push(j)}for(const [k,v] of Object.entries(r?.notes&&typeof r.notes==='object'?r.notes:{})){const j=map[Number(k)];if(/^\d+$/.test(k)&&Number.isInteger(j)&&j>=0&&typeof v==='string')out.notes[j]=v}if(keepReview)for(const key of ['quiz','quizAnswers','assessmentVersion','rubricScores','legacyReview'])if(r&&key in r)out[key]=r[key];return out}
