export function migrateRows(rows){if(!Array.isArray(rows))return rows;const parse=r=>{try{return JSON.parse(r.content)}catch{return null}};const out=rows.map(r=>({...r}));const byId=new Map(out.map(r=>[r.course_id,r]));for(const r of out){const a=ALIASES[r.course_id];if(a&&a.to===r.course_id){const w=parse(r);if(w&&w.layout!==LAYOUT)r.content=JSON.stringify({...w,...remap(w,a.map,true),layout:LAYOUT})}}for(const r of rows){const a=ALIASES[r.course_id];if(!a||a.to===r.course_id)continue;const w=parse(r);if(!w)continue;const target=byId.get(a.to);if(target){target.content=JSON.stringify(union(parse(target),remap(w,a.map,false),'the former “'+r.course_id+'” path'))}else{const row={course_id:a.to,content:JSON.stringify(union(null,remap(w,a.map,false),'the former “'+r.course_id+'” path')),updated_at:r.updated_at,migratedFrom:r.course_id};out.push(row);byId.set(a.to,row)}}return out}
